-- Casados por descrição (código antigo do catálogo diverge do PDF, produto é o mesmo):
-- CHURROS DOCE DE LEITE PCT 50 UNID / CHURROS DOCE DE CHOCOLATE PCT 50 UNID
UPDATE products SET cigam_code = '2003000014' WHERE trim(saibweb_code) = '20032';
UPDATE products SET cigam_code = '2003000024' WHERE trim(saibweb_code) = '20039';
-- COXINHA DE FRANGO C/ PANKO 1KG (produto sem código antigo no catálogo)
UPDATE products SET cigam_code = '2003000027' WHERE saibweb_code IS NULL AND name ILIKE 'Coxinha panko frango%';
